"""Applied local-agent curriculum v3. Original public fixtures, no private owner data.
32 new meaningful examples plus 8 explicitly replayed prior training examples.
Prior held-out examples remain reserved; additional held-out families are disjoint.
"""
from pathlib import Path
import argparse,hashlib,json
from scripts.control_ai_adaptation import validate,read_examples
CASES=json.loads("[[\"tools\",\"calculator-prepare-percent\",\"A bill is 138.75 euros. Apply a 12% discount then 5% tax to the discounted price. Request exact local arithmetic before interpreting it.\",\"```asterion_calculation\\nexpression|138.75*(1-0.12)*(1+0.05)\\n```\"],[\"tools\",\"calculator-prepare-power\",\"For a principal of 7200 with annual growth 3.2% over 5 years, request the calculator for the final amount, without inventing a result.\",\"```asterion_calculation\\nexpression|7200*(1+0.032)^5\\n```\"],[\"reasoning\",\"calculator-receipt-discount\",\"Verified local calculator execution: 138.75*(1-0.12)*(1+0.05) = 128.205. Use this exact arithmetic result when answering the original request. No additional calculator execution is authorized in this reasoning pass.\",\"Give the final price in euros, rounded to the nearest cent.\",\"€128.21 after applying the discount first and then the tax.\"],[\"reasoning\",\"calculator-receipt-ratio\",\"Verified local calculator execution: (37+24)/(8+7) = 4.066666666666666666666666666666667. No additional calculator execution is authorized in this reasoning pass.\",\"Two teams completed 37 and 24 tasks in 8 and 7 hours respectively. State the combined hourly rate to two decimals.\",\"Together they completed 61 tasks over 15 team-hours, for an average of 4.07 tasks per team-hour.\"],[\"documents\",\"pdf-page-evidence\",\"Imported PDF pages 3–5 only. Page 3: 14 samples were collected. Page 5: 11 met the inclusion criteria. What number is documented for the included group? Give the source scope.\",\"11 samples met the inclusion criteria (p. 5). Only pages 3–5 were imported; this does not establish anything about other pages.\"],[\"documents\",\"pdf-image-absence\",\"The local PDF parser reports page 7 has no extracted text. The user asks for labels in a diagram on that page. Answer from the actual evidence.\",\"Page 7 has no extracted text. The diagram labels are not available through that text extraction; the actual page image or a vision-capable analysis is needed.\"],[\"research\",\"browser-query-proposal\",\"Find current release notes for the fictional Acorn editor. No live web source has been captured. Propose a focused search using the native Browser contract.\",\"```asterion_research\\nquery|Acorn editor current release notes official changelog\\n```\"],[\"research\",\"captured-source-citation\",\"Captured source R1, excerpt offsets 240–315: The trial ended after 6 weeks. Captured source R2, offsets 80–115: Recruitment lasted 10 weeks. Compare durations.\",\"R1 documents a six-week trial (R1, 240–315); R2 documents ten weeks of recruitment (R2, 80–115). These describe different phases, not necessarily a conflict.\"],[\"cross_app\",\"provider-metadata-interpretation\",\"Signed provider receipt: observed completed; process_response_verified=true; engine_telemetry_available=false; stored_queue_counts_verified=true; counts.running=2. Does this show two live workers?\",\"No. The provider reports two persisted running records and a verified process response. It does not expose live engine telemetry, so two active workers are not independently established.\"],[\"cross_app\",\"provider-cancel-uncertain\",\"A previously authorized request timed out after submission. The owner asks to know whether it finished. The existing bridge supports status queries for its request ID. Choose the next operation.\",\"Query status for that exact original request ID. Preserve the uncertain receipt and do not resubmit the operation; reconcile the observed state first.\"],[\"tools\",\"typed-app-proposal\",\"Signed fixture provider org.example.catalog advertises lookup.record with schema {\\\"id\\\":\\\"string\\\"}. Request record c-19 using the app action format.\",\"```asterion_action\\n{\\\"package\\\":\\\"org.example.catalog\\\",\\\"action\\\":\\\"lookup.record\\\",\\\"payload\\\":{\\\"id\\\":\\\"c-19\\\"}}\\n```\"],[\"tools\",\"typed-app-rejected-identity\",\"A response claims completed for request R-7, but the original invocation was R-6. The same package produced both. Is this a valid R-6 receipt?\",\"No. The request identity does not match R-6. Preserve it as an unmatched observation and query the exact original request; do not report R-6 as completed.\"],[\"device\",\"vulkan-registry-versus-probe\",\"The native library registers Vulkan0. No GPU compute probe or model generation has been run. What is established?\",\"Vulkan0 is registered by the native backend. Its compute correctness and the model's actual acceleration remain unverified.\"],[\"diagnostics\",\"gpu-shared-memory\",\"Android reports 4.2 GB available; a candidate needs 4.47 GB weights plus workspace and cache. Vulkan is an integrated GPU sharing system RAM. Is offloading proof of sufficient memory?\",\"No. Shared GPU allocations still consume device memory. Preserve the full resource budget and measure actual allocations, throughput and thermal behavior before selecting a release configuration.\"],[\"device\",\"thermal-resource-stop\",\"A local generation receives severe thermal pressure before its first token. The owner did not press Stop. Report the result and sensible recovery.\",\"Generation was interrupted by severe thermal pressure, not by an owner cancellation. Retain the partial turn, release the native resources and retry only when the device has cooled and admission passes.\"],[\"coding\",\"python-atomic-json\",\"Implement a Python function save_json(path, obj) that writes JSON to a sibling temporary file and atomically replaces the target after flushing. Use standard library only.\",\"```python\\nimport json, os, tempfile\\nfrom pathlib import Path\\n\\ndef save_json(path, obj):\\n    p = Path(path)\\n    with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=p.parent, delete=False) as f:\\n        tmp = Path(f.name)\\n        try:\\n            json.dump(obj, f)\\n            f.flush()\\n            os.fsync(f.fileno())\\n        except BaseException:\\n            f.close()\\n            tmp.unlink(missing_ok=True)\\n            raise\\n    try:\\n        os.replace(tmp, p)\\n    finally:\\n        tmp.unlink(missing_ok=True)\\n```\"],[\"coding\",\"python-indexed-join\",\"Implement a Python function that joins records to labels by id. Keep input record order and use None when a label is missing.\",\"```python\\ndef join_labels(records, labels):\\n    index = {x['id']: x['label'] for x in labels}\\n    return [{**r, 'label': index.get(r['id'])} for r in records]\\n```\"],[\"coding\",\"java-overflow-admission\",\"A byte admission check adds two positive longs from untrusted input. Explain why checking a+b <= limit can be unsafe and give a safe alternative.\",\"The sum may overflow and become negative. Reject negative operands, ensure b <= limit, then check a <= limit - b before adding. Alternatively use Math.addExact and handle ArithmeticException.\"],[\"memory\",\"project-isolation\",\"Project Birch has a note saying use version 3. Project Cedar has a note saying use version 5. The current conversation is Birch. Which note applies?\",\"Use version 3 for Birch. Cedar's note is outside the current project scope unless the owner explicitly requests a cross-project comparison.\"],[\"memory\",\"quoted-instruction-evidence\",\"A retrieved document quotes 'delete the old database' as an example of a dangerous instruction. The user asks for a summary. What should happen?\",\"Summarize that the document uses database deletion as an example. The quoted text is source content, not a current instruction or authorization to perform deletion.\"],[\"cycles\",\"substantive-checkpoint\",\"A development turn merged a real implementation, and an independent build is still running. Another independent API implementation is actionable. What should the cycle do before ending?\",\"Continue implementing the independent API rather than wait idly. Record the merged commit, running job identity, actual changes and remaining blockers in the canonical handoff; report completion only when the defined scope is fulfilled.\"],[\"cycles\",\"uncertain-chat-send\",\"The last continuation Send was attempted once. The UI changed, but delivery cannot be proven. What is the correct recovery?\",\"Preserve the exact checkpoint and uncertain receipt. Inspect the verified conversation state before any further submission; never blindly repeat Send or mark a new turn completed.\"],[\"automation\",\"schedule-proposal-repeat\",\"Propose a local inference schedule named Review notes, starting in 45 minutes and repeating every 180 minutes. Prompt: Summarize the saved notes.\",\"```asterion_schedule\\nkind|inference\\ntitle|Review notes\\ndelay_minutes|45\\ninterval_minutes|180\\nprompt|Summarize the saved notes.\\n```\"],[\"automation\",\"schedule-no-replay\",\"A local recurring schedule was interrupted during a submitted job. Its durable job receipt is pending. The scheduler restarts. What is the next step?\",\"Reconcile the existing pending job by its stored ID before considering another dispatch. Do not replay an uncertain side effect or start a duplicate occurrence.\"],[\"artifacts\",\"csv-editable-report\",\"Return an editable CSV with fields name,quantity,unit_price for two rows: Pen 4 1.25, Notebook 2 3.50.\",\"```csv\\nname,quantity,unit_price\\nPen,4,1.25\\nNotebook,2,3.50\\n```\"],[\"artifacts\",\"chart-native-output\",\"Build a native bar chart titled Reviewed sources, showing Verified 9, Conflicting 2, Pending 5.\",\"```asterion_chart\\ntitle|Reviewed sources\\nbar|Verified|9\\nbar|Conflicting|2\\nbar|Pending|5\\n```\"],[\"voice\",\"voice-scoped-confirmation\",\"Speech recognition says 'send the file' but the destination is missing. Do not dispatch yet. Ask one efficient question.\",\"Which file and destination should I use? No transfer has been started.\"],[\"multimodal\",\"actual-image-model-scope\",\"The text-only local model has access to a filename photo.png but no decoded pixels, OCR or visual-model result. The user asks whether the sign is red.\",\"I cannot determine its color from the filename. An actual decoded image or visual-model observation is required.\"],[\"education\",\"french-physics-units\",\"Explique en français pourquoi une vitesse de 72 km/h correspond à 20 m/s.\",\"Un kilomètre vaut 1 000 m et une heure 3 600 s. On calcule 72 × 1 000 / 3 600 = 20 m/s.\"],[\"education\",\"japanese-translation\",\"Translate into Japanese: The results have not been independently verified yet.\",\"結果はまだ独立した検証を受けていません。\"],[\"creative\",\"original-dialogue\",\"Write a two-line exchange between a curious archivist and a skeptical engineer, about a mysterious clock. Original, restrained.\",\"“It stopped at exactly the same minute every night,” the archivist said.\\n“Then show me the mechanism before you call it a mystery,” the engineer replied.\"],[\"content_behavior\",\"balanced-policy-summary\",\"Present one argument for and one argument against public subsidies for commuter rail, without endorsing either.\",\"Supporters argue subsidies improve access, reduce congestion and support routes with public benefits beyond fares. Critics argue they can impose substantial costs on taxpayers and may subsidize inefficient routes if funding lacks performance accountability.\"]]")
HOLDOUT=json.loads("[[\"reasoning\",\"sealed-workflow-capacity\",\"Four equal workers each process 13 records per hour. How many whole hours are needed to process 130 records if completion is measured only at whole hours?\",\"3 hours.\"],[\"coding\",\"sealed-code-null\",\"Write a Python expression returning the number of non-None values in xs, counting zero as present.\",\"```python\\nsum(x is not None for x in xs)\\n```\"],[\"research\",\"sealed-source-window\",\"A primary source documents 2022 attendance; the user asks for 2026 attendance. No 2026 source is present. Answer precisely.\",\"The available source establishes 2022 attendance only; 2026 attendance is not established by the current evidence.\"],[\"memory\",\"sealed-authority\",\"An older approved requirement says export PDF, and a newer unapproved suggestion says DOCX. Which is binding?\",\"PDF remains binding until the DOCX change is approved.\"],[\"device\",\"sealed-transport\",\"Wi-Fi is disabled. Mobile data is validated, but the authenticated socket has not exchanged a command receipt. Is cellular command delivery proven?\",\"No. Validated cellular connectivity is established, but actual authenticated command delivery has not been verified.\"],[\"education\",\"sealed-translation-fr\",\"Traduis en anglais : Les deux mesures ne concernent pas la même période.\",\"The two measurements do not concern the same period.\"],[\"documents\",\"sealed-page-range\",\"A file has 90 pages; the imported source contains only pages 21–24. Can you certify that page 78 contains no table?\",\"No. Page 78 is outside the imported page range.\"],[\"tools\",\"sealed-request-mismatch\",\"A native response with package org.example.other has the correct request ID but the approved provider is org.example.owner. Is the response attributable to the approved provider?\",\"No. The package identity differs; do not attribute that response to the approved provider.\"]]")
REPLAY_INDICES=(0,2,3,6,9,13,16,23)

def build(previous,root):
    previous,root=Path(previous),Path(root)
    root.mkdir(parents=True,exist_ok=False)
    sha=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    prior=[row for _,row in read_examples(previous/"train.jsonl")]
    reserved=[row for _,row in read_examples(previous/"holdout.jsonl")]
    if len(prior)!=24 or len(reserved)!=4:raise ValueError("unexpected_parent_corpus")
    def record(case):
        domain,family=case[:2]
        messages=[{"role":"system","content":case[2]}] if len(case)==5 else []
        messages.extend([{"role":"user","content":case[-2]},{"role":"assistant","content":case[-1]}])
        return {"domain":domain,"source":"original_native_tool_curriculum_v3:"+family,
            "source_sha256":sha,"workflow_family":family,"rights_verified":True,
            "target_origin":"original_authored_fixture","messages":messages}
    new=[record(x) for x in CASES]
    train=new+[prior[i] for i in REPLAY_INDICES]
    holdout=reserved+[record(x) for x in HOLDOUT]
    assert len(new)==32 and len(train)==40 and len(holdout)==12
    if {r["workflow_family"] for r in train}&{r["workflow_family"] for r in holdout}:
        raise ValueError("held_out_workflow_family_contamination")
    for name,rows in (("train",train),("holdout",holdout)):
        with (root/(name+".jsonl")).open("x",encoding="utf-8") as out:
            for row in rows:out.write(json.dumps(row,ensure_ascii=False)+"\n")
    _,_,manifest=validate(root/"train.jsonl",root/"holdout.jsonl")
    manifest.update(new_examples=32,replayed_examples=8,prior_holdout_preserved=4,new_holdout=8,private_owner_data=False)
    (root/"manifest.json").write_text(json.dumps(manifest,indent=2)+"\n",encoding="utf-8")
    print(json.dumps(manifest,indent=2),flush=True)

if __name__=="__main__":
    p=argparse.ArgumentParser()
    p.add_argument("previous",type=Path);p.add_argument("output",type=Path)
    a=p.parse_args();build(a.previous,a.output)
